const categoriasValidas = [
  "urgente_prazo", "duvida_processo", "agendamento",
  "financeiro", "documento_recebido", "spam_irrelevante"
];

function converterDataParaISO(dataStr) {
  if (!dataStr) return null;
  const match = String(dataStr).match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (!match) return null; // formato inesperado, não quebra o fluxo
  const [, dia, mes, ano] = match;
  return `${ano}-${mes}-${dia}`;
}

const results = [];

for (const item of $input.all()) {
  let raw = item.json.output || "";

  raw = raw.replace(/```json\s*/gi, "").replace(/```\s*/g, "").trim();

  let parsed;
  let erro = null;

  try {
    parsed = JSON.parse(raw);
  } catch (e) {
    erro = "JSON inválido: " + e.message;
    parsed = {
      id: null,
      canal: null,
      de: null,
      categoria: "erro_parsing",
      nome_cliente: null,
      numero_processo: null,
      data_prazo: null,
      resumo: "Falha ao interpretar resposta da IA. Requer revisão manual.",
      remetente_tipo: "desconhecido",
      confianca: "baixa"
    };
  }

  if (!erro && !categoriasValidas.includes(parsed.categoria)) {
    erro = `Categoria fora do padrão retornada pela IA: "${parsed.categoria}"`;
    parsed.categoria = "duvida_processo";
    parsed.confianca = "baixa";
  }

  if (parsed.numero_processo && !/^\d{7}-\d{2}\.\d{4}\.\d\.\d{2}\.\d{4}$/.test(parsed.numero_processo)) {
    erro = (erro ? erro + " | " : "") + "numero_processo fora do padrão CNJ";
  }

  const dataPrazoOriginal = parsed.data_prazo;
  const dataPrazoISO = converterDataParaISO(dataPrazoOriginal);

  if (dataPrazoOriginal && !dataPrazoISO) {
    erro = (erro ? erro + " | " : "") + `data_prazo fora do padrão DD/MM/AAAA: "${dataPrazoOriginal}"`;
  }

  results.push({
    json: {
      ...parsed,
      data_prazo: dataPrazoISO, // agora já sai em AAAA-MM-DD, pronto pro tipo `date` do Postgres
      erro_processamento: erro,
      processado_em: new Date().toISOString()
    }
  });
}

return results;
